create extension if not exists pgcrypto;
create type public.foncier_pipeline as enum ('new','qualify','contacted','appointment','study','mandate_proposal','mandate_signed','promoter_presentation','offer','agreement','sold','follow_up','not_relevant','abandoned');
create table public.foncier_land_leads(id uuid primary key default gen_random_uuid(),reference text unique not null default ('PKF-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),first_name text not null,last_name text not null,phone text not null,email text,preferred_channel text,marketing_consent boolean not null default false,privacy_consent boolean not null default false,island text,commune text not null,district text,location text,cadastre text,surface numeric check(surface>0),access text,visibility text,topography text,shape text,frontage numeric,current_state text,water text,electricity text,sanitation text,legal_status text,owner_goal text,timeline text,comment text,source text default 'website',qualification_score int check(qualification_score between 0 and 100),qualification_reasons jsonb not null default '{}'::jsonb,potential_projects text[] not null default '{}',pipeline public.foncier_pipeline not null default 'new',priority boolean not null default false,next_action text,next_follow_up timestamptz,assigned_to uuid references auth.users(id));
create table public.foncier_feasibility(id uuid primary key default gen_random_uuid(),land_id uuid not null unique references public.foncier_land_leads(id) on delete cascade,pga text,zone text,allowed_uses text,height_rule text,site_coverage text,setbacks text,parking text,access_notes text,networks text,sanitation_notes text,servitudes text,natural_risks text,environmental_constraints text,legal_notes text,division_options text,technical_notes text,documents_needed text,sources jsonb not null default '[]',verified_at timestamptz,validation_status text not null default 'to_verify' check(validation_status in ('to_verify','in_review','validated')),validated_by uuid references auth.users(id),updated_at timestamptz default now());
create table public.foncier_promoters(id uuid primary key default gen_random_uuid(),reference text unique not null default ('PKP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),created_at timestamptz not null default now(),company text not null,contact_name text not null,phone text not null,email text not null,areas text[] not null default '{}',surface_min numeric,surface_max numeric,budget_min numeric,budget_max numeric,project_types text[] not null default '{}',access_preferences text,constraints text,timeline text,comments text,privacy_consent boolean not null default false,status text not null default 'active');
create table public.foncier_matches(id uuid primary key default gen_random_uuid(),land_id uuid not null references public.foncier_land_leads(id) on delete cascade,promoter_id uuid not null references public.foncier_promoters(id) on delete cascade,score int not null check(score between 0 and 100),classification text not null,matched jsonb not null default '[]',to_verify jsonb not null default '[]',explanation text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(land_id,promoter_id));
create table public.foncier_activities(id uuid primary key default gen_random_uuid(),land_id uuid references public.foncier_land_leads(id) on delete cascade,promoter_id uuid references public.foncier_promoters(id) on delete cascade,actor_id uuid references auth.users(id),kind text not null,body text,metadata jsonb not null default '{}',due_at timestamptz,completed_at timestamptz,created_at timestamptz default now());
create table public.foncier_notifications(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),kind text not null,title text not null,body text,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz default now());
create table public.foncier_settings(id text primary key,value jsonb not null,updated_at timestamptz default now(),updated_by uuid references auth.users(id));
insert into public.foncier_settings(id,value) values('qualification_weights','{"surface":12,"access":12,"visibility":8,"topography":8,"networks":12,"legal":7,"timeline":6}'::jsonb),('google_sheets','{"status":"not_connected","sheet_name":"Suivi KW Impact"}'::jsonb) on conflict do nothing;
alter table public.foncier_land_leads enable row level security;alter table public.foncier_feasibility enable row level security;alter table public.foncier_promoters enable row level security;alter table public.foncier_matches enable row level security;alter table public.foncier_activities enable row level security;alter table public.foncier_notifications enable row level security;alter table public.foncier_settings enable row level security;
create policy "authenticated admin land" on public.foncier_land_leads for all to authenticated using(true) with check(true);create policy "authenticated admin feasibility" on public.foncier_feasibility for all to authenticated using(true) with check(true);create policy "authenticated admin promoters" on public.foncier_promoters for all to authenticated using(true) with check(true);create policy "authenticated admin matches" on public.foncier_matches for all to authenticated using(true) with check(true);create policy "authenticated admin activities" on public.foncier_activities for all to authenticated using(true) with check(true);create policy "own notifications" on public.foncier_notifications for all to authenticated using(user_id=auth.uid() or user_id is null) with check(user_id=auth.uid() or user_id is null);create policy "authenticated settings" on public.foncier_settings for all to authenticated using(true) with check(true);
create index foncier_land_pipeline_idx on public.foncier_land_leads(pipeline,created_at desc);create index foncier_land_commune_idx on public.foncier_land_leads(commune);create index foncier_followup_idx on public.foncier_land_leads(next_follow_up) where next_follow_up is not null;create index foncier_activity_due_idx on public.foncier_activities(due_at) where completed_at is null;
create or replace function public.refresh_foncier_matches() returns integer language plpgsql security definer set search_path=public as $$declare l public.foncier_land_leads%rowtype;p public.foncier_promoters%rowtype;s int;matched jsonb;checks jsonb;count_rows int:=0;begin delete from public.foncier_matches;for l in select * from public.foncier_land_leads where pipeline not in ('abandoned','not_relevant','sold') loop for p in select * from public.foncier_promoters where status='active' loop s:=0;matched:='[]'::jsonb;checks:='[]'::jsonb;if exists(select 1 from unnest(p.areas) a where lower(l.commune) like '%'||lower(a)||'%' or lower(a) like '%'||lower(l.commune)||'%') then s:=s+30;matched:=matched||'"Localisation"'::jsonb;else checks:=checks||'"Localisation"'::jsonb;end if;if (p.surface_min is null or l.surface>=p.surface_min) and (p.surface_max is null or l.surface<=p.surface_max) then s:=s+25;matched:=matched||'"Surface"'::jsonb;else checks:=checks||'"Surface"'::jsonb;end if;if l.potential_projects && p.project_types then s:=s+25;matched:=matched||'"Typologie de programme"'::jsonb;else checks:=checks||'"Typologie de programme"'::jsonb;end if;if l.access ilike '%direct%' then s:=s+10;matched:=matched||'"Accès déclaré"'::jsonb;else checks:=checks||'"Accès"'::jsonb;end if;if p.budget_min is null and p.budget_max is null then checks:=checks||'"Budget non comparable"'::jsonb;else s:=s+5;checks:=checks||'"Prix du terrain à établir"'::jsonb;end if;s:=least(100,s);insert into public.foncier_matches(land_id,promoter_id,score,classification,matched,to_verify,explanation) values(l.id,p.id,s,case when s>=75 then 'strong' when s>=45 then 'partial' when s<25 then 'incompatible' else 'insufficient_data' end,matched,checks,'Score indicatif fondé sur la localisation, la surface, les typologies, l’accès et le budget disponible. Il ne vaut pas engagement d’achat.');count_rows:=count_rows+1;end loop;end loop;return count_rows;end$$;
revoke all on function public.refresh_foncier_matches() from public;grant execute on function public.refresh_foncier_matches() to authenticated;
